-- 真实配对准备事实；日历显式配置，不生成胜负/奖励。
CREATE TABLE IF NOT EXISTS p13_union_fight_matches (id CHAR(64) PRIMARY KEY,day VARCHAR(10) NOT NULL,`group` CHAR(1) NOT NULL,round INT NOT NULL,left_guild_id VARCHAR(64) NOT NULL,right_guild_id VARCHAR(64) NOT NULL,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,left_preview LONGBLOB NOT NULL,right_preview LONGBLOB NOT NULL,roster LONGBLOB NOT NULL,snapshot_hash CHAR(64) NOT NULL,configuration_hash CHAR(64) NOT NULL,engine_version VARCHAR(128) NOT NULL,client_version VARCHAR(128) NOT NULL,created_at BIGINT NOT NULL,source TEXT NOT NULL,INDEX idx_p13_match_day(day),INDEX idx_p13_left_guild(left_guild_id),INDEX idx_p13_right_guild(right_guild_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
